const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const PORT = process.env.PORT || 80;

app.use(cors());
app.use(bodyParser.json());
app.use(express.static(path.join(__dirname, 'dist')));

const dbBaseConfig = {
  host: process.env.DB_HOST || '192.168.21.60', 
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '249gaqLY4pdeHH71T8',
  port: parseInt(process.env.DB_PORT || '3306'),
  connectTimeout: 15000 
};

const DB_NAME = process.env.DB_NAME || 'tiangong_db';
let pool = null;

// 通用日志记录函数
async function logToDB(level, module, message) {
  if (!pool) {
    console.log(`[${level}] [${module}] ${message}`);
    return;
  }
  try {
    await pool.query(
      'INSERT INTO system_logs (level, module, message) VALUES (?, ?, ?)',
      [level, module, message]
    );
  } catch (err) {
    console.error('Failed to write log to DB:', err.message);
  }
}

async function initDB() {
  console.log(`[DB] 正在建立中枢连接: ${dbBaseConfig.host}...`);
  try {
    const tempConn = await mysql.createConnection(dbBaseConfig);
    await tempConn.query(`CREATE DATABASE IF NOT EXISTS ${DB_NAME} CHARACTER SET utf8mb4`);
    await tempConn.end();

    pool = mysql.createPool({
      ...dbBaseConfig,
      database: DB_NAME,
      waitForConnections: true,
      connectionLimit: 15
    });

    // 创建表结构
    await pool.query(`CREATE TABLE IF NOT EXISTS roles (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) UNIQUE, description VARCHAR(255))`);
    await pool.query(`CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE, password VARCHAR(100), real_name VARCHAR(100), role_id INT)`);
    await pool.query(`CREATE TABLE IF NOT EXISTS announcements (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200), content TEXT, app_context VARCHAR(50), priority VARCHAR(20), publish_date DATETIME DEFAULT CURRENT_TIMESTAMP)`);
    await pool.query(`CREATE TABLE IF NOT EXISTS sub_apps (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100), description TEXT, icon_type VARCHAR(50), color_theme VARCHAR(50), sort_order INT DEFAULT 0)`);
    await pool.query(`CREATE TABLE IF NOT EXISTS data_sources (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100), type VARCHAR(20), host VARCHAR(100), status VARCHAR(20) DEFAULT 'online')`);
    await pool.query(`CREATE TABLE IF NOT EXISTS servers (id VARCHAR(50) PRIMARY KEY, hostname VARCHAR(100), ip VARCHAR(50), status VARCHAR(20), env VARCHAR(20), cpu_cores INT, memory_gb INT)`);

    // 日志表
    await pool.query(`
      CREATE TABLE IF NOT EXISTS system_logs (
        id INT AUTO_INCREMENT PRIMARY KEY,
        level VARCHAR(20) NOT NULL,
        module VARCHAR(50),
        message TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);

    // 初始化数据
    const [appsCount] = await pool.query('SELECT count(*) as count FROM sub_apps');
    if (appsCount[0].count === 0) {
      await pool.query("INSERT INTO roles (name, description) VALUES ('admin', '超级管理员')");
      await pool.query("INSERT INTO users (username, password, real_name, role_id) VALUES ('Admin', 'admin123', '系统管理员', 1)");
      await pool.query(`
        INSERT INTO sub_apps (id, name, description, icon_type, color_theme, sort_order) VALUES 
        ('DATABASE_MANAGER', '数据库管理', '实例生命周期与巡检', 'Database', 'blue', 1),
        ('SERVER_MANAGER', '资产管理系统', 'CMDB与主机监控', 'Server', 'indigo', 2),
        ('LOG_CENTER', '日志中心', '应用运行日志与审计看板', 'Terminal', 'slate', 3),
        ('SECURITY_AUDIT', '安全合规', '漏洞扫描与基线检查', 'Shield', 'amber', 4)
      `);
      await logToDB('INFO', 'SYSTEM', '天工平台核心元数据初始化完成');
    }

    await logToDB('INFO', 'DB_INIT', `连接池已建立，最大连接数: 15`);
  } catch (err) {
    console.error('[DB] CRITICAL ERROR:', err.message);
  }
}

const checkDb = (req, res, next) => { if (!pool) return res.status(503).json({ error: 'DATABASE_DISCONNECTED' }); next(); };

app.post('/api/login', checkDb, async (req, res) => {
  const { username, password } = req.body;
  try {
    const [users] = await pool.query('SELECT * FROM users WHERE username = ? AND password = ?', [username, password]);
    if (users.length > 0) {
      await logToDB('INFO', 'AUTH', `用户 ${username} 成功通过 Web 控制台登录`);
      res.json({ success: true, user: users[0] });
    } else {
      await logToDB('WARN', 'AUTH', `非法登录尝试: 账号 ${username}`);
      res.status(401).json({ success: false, error: '认证失败' });
    }
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/portal/data', checkDb, async (req, res) => {
  const [apps] = await pool.query('SELECT * FROM sub_apps ORDER BY sort_order');
  const [ann] = await pool.query('SELECT * FROM announcements ORDER BY publish_date DESC');
  res.json({ success: true, apps, announcements: ann });
});

app.get('/api/logs', checkDb, async (req, res) => {
  const { level, limit = 50 } = req.query;
  let query = 'SELECT * FROM system_logs';
  const params = [];
  if (level) {
    query += ' WHERE level = ?';
    params.push(level);
  }
  query += ' ORDER BY timestamp DESC LIMIT ?';
  params.push(parseInt(limit));

  const [rows] = await pool.query(query, params);
  res.json({ success: true, data: rows });
});

app.get('/api/servers', checkDb, async (req, res) => {
  const [rows] = await pool.query('SELECT * FROM servers');
  res.json({ success: true, data: rows });
});

app.get('*', (req, res) => res.sendFile(path.join(__dirname, 'dist', 'index.html')));

app.listen(PORT, async () => {
  console.log(`[SYS] O&M Platform started on port ${PORT}`);
  await initDB();
});

import React, { useState, useEffect, useRef } from 'react';
import { 
  Terminal, Search, Filter, RefreshCw, Trash2, 
  Download, Play, Pause, AlertCircle, Info, Bug, ShieldAlert 
} from 'lucide-react';
import { LogEntry } from '../../types';

const LogCenter: React.FC = () => {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [isLive, setIsLive] = useState(true);
  const [filterLevel, setFilterLevel] = useState<string>('');
  const logEndRef = useRef<HTMLDivElement>(null);

  const fetchLogs = async () => {
    try {
      const res = await fetch(`/api/logs?${filterLevel ? `level=${filterLevel}` : ''}`);
      const data = await res.json();
      if (data.success) setLogs(data.data);
    } catch (e) {
      console.error("Fetch logs failed");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs();
    let interval: any;
    if (isLive) {
      interval = setInterval(fetchLogs, 3000);
    }
    return () => clearInterval(interval);
  }, [isLive, filterLevel]);

  const getLevelStyle = (level: string) => {
    switch(level) {
      case 'ERROR': return 'text-red-400 bg-red-400/10 border-red-400/20';
      case 'WARN': return 'text-amber-400 bg-amber-400/10 border-amber-400/20';
      case 'DEBUG': return 'text-blue-400 bg-blue-400/10 border-blue-400/20';
      default: return 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
    }
  };

  return (
    <div className="h-[calc(100vh-64px)] flex flex-col bg-slate-950 text-slate-300 font-mono">
      {/* Log Header / Toolbar */}
      <div className="p-4 bg-slate-900/50 border-b border-white/5 flex items-center justify-between">
        <div className="flex items-center space-x-6">
          <div className="flex items-center space-x-2">
            <Terminal className="w-5 h-5 text-indigo-400" />
            <h2 className="text-sm font-black uppercase tracking-widest text-white">Centralized System Logs</h2>
          </div>
          <div className="h-4 w-px bg-white/10"></div>
          <div className="flex items-center space-x-2 bg-slate-800/50 rounded-lg px-3 py-1.5 border border-white/5">
             <Filter className="w-3.5 h-3.5 text-slate-500" />
             <select 
               className="bg-transparent border-none outline-none text-xs font-bold text-slate-400"
               value={filterLevel}
               onChange={(e) => setFilterLevel(e.target.value)}
             >
               <option value="">ALL LEVELS</option>
               <option value="INFO">INFO</option>
               <option value="WARN">WARN</option>
               <option value="ERROR">ERROR</option>
               <option value="DEBUG">DEBUG</option>
             </select>
          </div>
        </div>

        <div className="flex items-center space-x-3">
          <button 
            onClick={() => setIsLive(!isLive)}
            className={`flex items-center space-x-2 px-4 py-1.5 rounded-lg text-xs font-black transition-all ${isLive ? 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20' : 'bg-slate-800 text-slate-400 border border-white/5'}`}
          >
            {isLive ? <RefreshCw className="w-3 h-3 animate-spin" /> : <Play className="w-3 h-3" />}
            <span>{isLive ? 'LIVE STREAMING' : 'PAUSED'}</span>
          </button>
          <button className="p-2 hover:bg-white/5 rounded-lg text-slate-500 hover:text-white transition-colors"><Download className="w-4 h-4" /></button>
          <button className="p-2 hover:bg-white/5 rounded-lg text-slate-500 hover:text-red-400 transition-colors"><Trash2 className="w-4 h-4" /></button>
        </div>
      </div>

      {/* Log Content Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-2 custom-scrollbar">
        {loading ? (
          <div className="flex items-center justify-center h-full text-slate-600 animate-pulse">
            Establishing secure log channel...
          </div>
        ) : (
          logs.map((log) => (
            <div key={log.id} className="flex items-start space-x-4 group hover:bg-white/5 py-1 px-2 rounded-md transition-colors border-l-2 border-transparent hover:border-indigo-500">
               <span className="text-slate-600 shrink-0 text-[11px] mt-0.5">[{new Date(log.timestamp).toLocaleTimeString()}]</span>
               <span className={`text-[10px] font-black px-2 py-0.5 rounded border ${getLevelStyle(log.level)} shrink-0 w-16 text-center`}>
                 {log.level}
               </span>
               <span className="text-indigo-400/80 font-bold text-[11px] shrink-0 w-24">@{log.module}</span>
               <span className="text-slate-200 text-sm font-medium whitespace-pre-wrap leading-relaxed">{log.message}</span>
            </div>
          ))
        )}
        <div ref={logEndRef} />
      </div>

      {/* Footer Info */}
      <div className="px-6 py-2 bg-indigo-600 text-white text-[10px] font-black flex justify-between items-center uppercase tracking-widest">
         <div className="flex items-center space-x-4">
            <span>Server: Cluster-Nexus-01</span>
            <span>Latency: 12ms</span>
         </div>
         <div className="flex items-center space-x-4">
            <span>Buffer: {logs.length}/500</span>
            <span className="bg-white/20 px-2 py-0.5 rounded">v2.8.5-CORE</span>
         </div>
      </div>
    </div>
  );
};

