async function logMessage(level, module, message) {
  const timestamp = new Date().toLocaleString();
  const logEntry = `[${timestamp}] [${level}] [${module}] ${message}`;

  // 1. 始终输出到控制台（这是您本地运行 node server.js 最直观能看到的）
  if (level === 'ERROR') {
